{"command": "python3 -c "
from PIL import Image, ImageOps, ImageDraw
im = ImageOps.autocontrast(Image.open('radiograph.jpg').convert('L'), cutoff=1)
w,h=im.size
# Upper arch: y 0.33-0.62, x 0.22-0.62 and 0.55-0.80
for n,(x1,x2) in {'U1':(0.20,0.60),'U2':(0.55,0.85)}.items():
    c = im.crop((int(w*x1),int(h*0.33),int(w*x2),int(h*0.62)))
    c = c.resize((c.width*3,c.height*3), Image.LANCZOS)
    d=ImageDraw.Draw(c)
    for i in range(1,40):
        fx=x1+i*0.01
        if fx<x2:
            px=(fx-x1)/(x2-x1)*c.width
            d.line([(px,0),(px,c.height)],fill=(255,0,0),width=1)
            if i%2==0: d.text((px+1,2),f'{fx:.2f}',fill=(255,255,0))
    for j in range(1,30):
        fy=0.33+j*0.01
        if fy<0.62:
            py=(fy-0.33)/0.29*c.height
            d.line([(0,py),(c.width,py)],fill=(0,0,255),width=1)
            d.text((2,py+1),f'{fy:.2f}',fill=(0,255,255))
    c.save(f'/tmp/g_{n}.png'); print(n,c.size)
"", "description": "Gridded upper arch crops"}

